class SupportView extends StatelessWidget {
  const SupportView({super.key});

  static const String routeName = "/support";

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final isDesktop = Util.isDesktop;

    return ConditionalParent(
      condition: !isDesktop,
      builder: (child) {
        return Background(
          child: Scaffold(
            backgroundColor: Theme.of(context)
                .extension<StackColors>()!
                .background,
            appBar: AppBar(
              leading: AppBarBackButton(
                onPressed: () {
                  Navigator.of(context).pop();
                },
              ),
              title: Text(
                l10n.settingsSupport,
                style: STextStyles.navBarTitle(context),
              ),
            ),
            body: SafeArea(
              child: Padding(padding: const EdgeInsets.all(16), child: child),
            ),
          ),
        );
      },
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          RoundedWhiteContainer(
            child: Text(
              l10n.supportText,
              style: STextStyles.smallMed12(context),
            ),
          ),
          isDesktop ? const SizedBox(height: 24) : const SizedBox(height: 12),
          for (final (i, link) in AppConfig.supportLinks.indexed) ...[
            if (i > 0) const SizedBox(height: 8),
            AboutItem(
              linkUrl: link.url,
              label: switch (link.channel) {
                SupportChannel.telegram => "Telegram",
                SupportChannel.discord => "Discord",
                SupportChannel.reddit => "Reddit",
                SupportChannel.x => "X",
                SupportChannel.email => l10n.supportEmail,
              },
              buttonText: link.text,
              iconAsset: switch (link.channel) {
                SupportChannel.telegram => Assets.socials.telegram,
                SupportChannel.discord => Assets.socials.discord,
                SupportChannel.reddit => Assets.socials.reddit,
                SupportChannel.x => Assets.socials.twitter,
                SupportChannel.email => Assets.svg.envelope,
              },
              isDesktop: isDesktop,
              email: link.channel == SupportChannel.email,
            ),
          ],
        ],
      ),
    );
  }
}

class AboutItem extends StatelessWidget {
  const AboutItem({
    super.key,
    required this.linkUrl,
    required this.label,
    required this.buttonText,
    required this.iconAsset,
    required this.isDesktop,
    this.email = false,
  });

  final String linkUrl;
  final String label;
  final String buttonText;
  final String iconAsset;
  final bool isDesktop;

  /// An email address: opened without the scam warning.
  final bool email;

  @override
  Widget build(BuildContext context) {
    final double iconSize = isDesktop ? 20 : 28;

    return RoundedWhiteContainer(
      padding: const EdgeInsets.all(0),
      child: RawMaterialButton(
        // splashColor: Theme.of(context).extension<StackColors>()!.highlight,
        materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(
            Constants.size.circularBorderRadius,
          ),
        ),
        onPressed: () async {
          if (email) {
            await launchUrl(
              Uri.parse(linkUrl),
              mode: LaunchMode.externalApplication,
            );
          } else {
            await showDialog<void>(
              context: context,
              builder: (_) => ScamWarningDialog(
                channel: label,
                onUnderstandPressed: () => launchUrl(
                  Uri.parse(linkUrl),
                  mode: LaunchMode.externalApplication,
                ),
              ),
            );
          }
        },
        child: Padding(
          padding: isDesktop
              ? const EdgeInsets.symmetric(horizontal: 20, vertical: 15)
              : const EdgeInsets.symmetric(horizontal: 12, vertical: 20),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  ConditionalParent(
                    condition: isDesktop,
                    builder: (child) => Container(
                      width: 40,
                      height: 40,
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(10000),
                        color: Theme.of(context)
                            .extension<StackColors>()!
                            .buttonBackSecondary,
                      ),
                      child: Center(child: child),
                    ),
                    child: SvgPicture.asset(
                      iconAsset,
                      width: iconSize,
                      height: iconSize,
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .topNavIconPrimary,
                    ),
                  ),
                  const SizedBox(width: 12),
                  Text(
                    label,
                    style: STextStyles.titleBold12(context),
                    textAlign: TextAlign.left,
                  ),
                ],
              ),
              if (isDesktop)
                Text(
                  buttonText,
                  style: STextStyles.desktopTextExtraExtraSmall(context),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class ScamWarningDialog extends StatelessWidget {
  const ScamWarningDialog({
    super.key,
    required this.onUnderstandPressed,
    required this.channel,
  });

  final String channel;
  final VoidCallback onUnderstandPressed;

  @override
  Widget build(BuildContext context) {
    return SDialog(
      padding: EdgeInsets.all(Util.isDesktop ? 32 : 16),
      child: ConditionalParent(
        condition: Util.isDesktop,
        builder: (child) => IntrinsicWidth(child: child),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            RichText(
              text: TextSpan(
                style: Util.isDesktop
                    ? STextStyles.w500_16(context)
                    : STextStyles.w500_14(context),
                children: [
                  TextSpan(
                    text: "${l10n.supportScamTitle}\n\n",
                    style: Util.isDesktop
                        ? STextStyles.desktopH2(context)
                        : STextStyles.pageTitleH2(context),
                  ),
                  ...l10nSpans(
                    "${l10n.supportScamOfficial(AppConfig.appName, channel)}\n\n",
                    style: const TextStyle(fontWeight: FontWeight.normal),
                    bold: const TextStyle(fontWeight: FontWeight.bold),
                  ),
                ],
              ),
            ),
            _Bullet(text: "${l10n.supportScamNoDms}\n"),
            _Bullet(text: "${l10n.supportScamNoShare}\n"),
            _Bullet(text: "${l10n.supportScamMoney}\n\n"),
            RichText(
              text: TextSpan(
                style: Util.isDesktop
                    ? STextStyles.w500_16(context)
                    : STextStyles.w500_14(context),
                children: l10nSpans(
                  l10n.supportScamNever,
                  style: const TextStyle(fontWeight: FontWeight.normal),
                  bold: const TextStyle(
                    fontStyle: FontStyle.italic,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),
            SizedBox(height: Util.isDesktop ? 40 : 32),
            Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                if (!Util.isDesktop) const Spacer(),
                ConditionalParent(
                  condition: !Util.isDesktop,
                  builder: (child) => Expanded(child: child),
                  child: PrimaryButton(
                    width: Util.isDesktop ? 240 : null,
                    buttonHeight: Util.isDesktop ? ButtonHeight.l : null,
                    label: l10n.supportIUnderstandCaps,
                    onPressed: onUnderstandPressed,
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

